window.careersTranslationsEn={"nhan-vien-qc-phong-sach":{title:"Cleanroom QC & HEPA Filter Quality Inspector",department:"Quality Control",type:"Full-time",location:"Ho Chi Minh City",experience:"Entry-level candidates accepted",salary:"Negotiable",workingHours:"Monday to Saturday",summary:"Inspect HEPA filter quality, operate Scan Test and Smoke Test equipment, and inspect VAF cleanroom equipment.",description:["Inspect air filter quality during production and before dispatch.","Check product appearance, dimensions, construction and technical parameters.","Evaluate HEPA filters and other air filtration products against VAF technical requirements.","Operate Scan Test equipment to verify efficiency and locate HEPA filter leaks.","Perform Smoke Tests to verify airflow direction, tightness and airflow control in clean areas.","Measure tightness, differential pressure, airflow and relevant cleanroom equipment parameters.","Inspect and accept HEPA Boxes, FFUs, Air Showers, Pass Boxes, Laminar Air Flow units and cleanroom systems.","Record results, prepare inspection reports and maintain QC documentation.","Coordinate non-conforming product handling and quality improvement actions."],requirements:["Technical college or university education in electrical, electronics, mechanical, environmental, automation or a related field.","Knowledge of quality inspection, cleanrooms, HVAC or air filtration is an advantage.","Experience with Scan Test, differential pressure, airflow or Smoke Test equipment is an advantage.","Able to read basic drawings and technical specifications.","Careful, honest, responsible and able to work independently and collaboratively.","Able to visit project sites when required.","Candidates with limited experience may be trained if they have a suitable technical foundation."],benefits:["Negotiable salary based on capability and experience.","Training in HEPA inspection, Scan Test, Smoke Test and cleanroom standards.","Overtime allowance and company-provided lunch.","Uniform and job equipment provided.","Full statutory insurance and company benefits.","Stable workplace with development opportunities in air filtration and cleanrooms."]},"nhan-vien-bao-tri":{title:"Maintenance Technician",department:"Maintenance",type:"Full-time",location:"Ho Chi Minh City",experience:"Maintenance experience required",salary:"Negotiable",workingHours:"Monday to Saturday",summary:"Maintain and repair electrical systems, production machinery, auxiliary equipment and company facilities.",description:["Maintain and repair machinery and equipment across the company.","Periodically inspect electrical systems, panels, production machinery, office equipment and facilities.","Troubleshoot industrial electrical systems and production equipment.","Monitor machinery condition and address potential failures promptly.","Develop and implement preventive maintenance plans.","Repair lighting, pumps, fans, air compressors and auxiliary equipment.","Coordinate with external service providers for specialist repairs.","Manage maintenance tools, materials and spare parts.","Maintain repair records and equipment condition reports.","Support installation, wiring and commissioning of new equipment."],requirements:["Technical college or university education in electrical, industrial electrical, electronics, mechatronics, automation or a related field.","Experience maintaining electrical systems and factory machinery.","Able to read electrical diagrams and troubleshoot basic electrical faults.","Able to use electrical measuring and specialist repair tools.","Experience with production machines, panels, inverters, motors or compressed air systems is preferred.","Responsible, proactive, safety-conscious and available for overtime incident support when necessary."],benefits:["Negotiable salary based on capability and experience.","Overtime and job-related allowances.","Company lunch, tools, uniform and personal protective equipment.","Full statutory insurance and company benefits.","Stable long-term work with exposure to a wide range of production equipment."]},"nhan-vien-nhan-su":{title:"Human Resources Officer",department:"Human Resources",type:"Full-time",location:"Ho Chi Minh City",experience:"At least 4–5 years",salary:"Negotiable",workingHours:"Monday to Friday",summary:"Manage recruitment, employee records, attendance, statutory insurance and HR policies at VAF.",description:["Handle recruitment requests, job posting, CV screening and interview scheduling.","Process onboarding, probation, employment contracts, transfers and offboarding.","Manage employee files, contracts and HR decisions.","Track attendance, annual leave, overtime and payroll input data.","Handle social, health and unemployment insurance procedures and employee claims.","Monitor new, renewed and terminated employment contracts.","Draft HR notices, decisions, procedures and regulations.","Support salary, bonus, allowance and employee benefit policies.","Monitor and apply updates to labour regulations.","Support labour rules, collective agreements and related records.","Answer employee questions about salary, insurance and policies.","Prepare periodic HR reports and perform other HR administration duties."],requirements:["College or university degree in human resources, law, administration, accounting or a related field.","At least 4–5 years of HR experience.","Hands-on experience with statutory social insurance procedures.","Strong knowledge of labour, payroll, insurance and employment contract regulations.","Able to manage employee records systematically.","Good Microsoft Word and Excel skills.","Strong communication, problem-solving and coordination skills.","Careful, trustworthy, confidential and highly responsible.","Manufacturing or factory HR experience is preferred."],benefits:["Competitive negotiable salary based on capability and experience.","Company allowances and lunch support.","Full statutory insurance.","Holiday, Tet, performance and other company benefits.","Stable and professional working environment.","Opportunity to help develop and improve the company HR management system."]}};